PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE Buff(
  Id Integer PRIMARY KEY,
  Name_EN TEXT,
  Desc_EN TEXT,
  Name_TC TEXT,
  Desc_TC TEXT,
  Name_JP TEXT,
  Desc_JP TEXT,
  Name_KR TEXT,
  Desc_KR TEXT
 );
CREATE TABLE Map(
   Id Integer PRIMARY KEY,
   Name_EN TEXT,
   Name_TC TEXT,
   Name_JP TEXT,
   Name_KR TEXT
 );
CREATE TABLE Monster(
   Id Integer PRIMARY KEY,
   Name_EN TEXT,
   Name_TC TEXT,
   Name_JP TEXT,
   Name_KR TEXT,
   type INTEGER
 );
CREATE TABLE Skill(
   Id Integer PRIMARY KEY,
   Name_EN TEXT,
   Name_TC TEXT,
   Name_JP TEXT,
   Name_KR TEXT
 );
COMMIT;

