INSERT INTO Buff VALUES(29011,'Freezing ','Being unable to move for 5 sec. ','凍結','5秒間無法移動','氷結','5秒間、動けなくなる。','빙결','5초간 움직일 수 없습니다.');
INSERT INTO Buff VALUES(29012,'Adamant ','Being Invincible for 3 sec ','金剛','3秒間，處於無敵狀態','金剛','3秒間、無敵状態になる。','금강','3초 동안 무적 상태가 됩니다.');
INSERT INTO Buff VALUES(29013,'Sleep ','Being slept for 10 sec. Player recovers 30%% of HP when gets hit or after 10 sec. ','睡眠','10秒間進入睡眠狀態，遭受攻擊或10秒後體力恢復30%%','睡眠','10秒間、睡眠状態になる。10秒間経過するか、睡眠中にダメージを受けるとHP30%%を回復する。','수면','10초 동안 캐릭터가 수면 상태가 되며, 피격 또는 10초가 지나면 체력이 30%% 회복됩니다.');
INSERT INTO Buff VALUES(29014,'HP Loss','Constantly loses 2%% of HP per sec in 5 sec (Max. 5 stacks)','體力減少',replace('5秒間，體力每秒減少2%%\n（最多疊加5層）','\n',char(10)),'HP減少','5秒間、1秒ごとにHPが2%%ずつ減少する。(最大5重複)','HP 감소',replace('5초 매 초당 HP가 2%%씩 감소합니다.\n(최대 5중첩)','\n',char(10)));
INSERT INTO Buff VALUES(29015,'Blood Drain','When you make a Direct Attack within 5 sec, player will recover 5%% of HP. ','吸血','命中時，5秒間體力恢復5%%','吸血','5秒間、攻撃が的中するとHPを5%%回復する。','흡혈',replace('5초 동안 공격이 적중하면 \nHP를 5%% 회복합니다.','\n',char(10)));
INSERT INTO Buff VALUES(29016,'Paralysis','Being unable to move. ','麻痹','無法行動','麻痺','キャラクターが動けなくなる。','마비','캐릭터가 움직일 수 없습니다');
