INSERT INTO Buff VALUES(63701,'Sudden Chill','Movement Speed Down due to Sudden Chill. ','寒氣','感受到一股惡寒 ','寒気','強力な冷気で動きが遅くなる。 ','한기','강력한 냉기에 몸이 느려집니다. ');
INSERT INTO Buff VALUES(63702,'Frostbite','Constantly lose HP due to Frostbite.','凍傷','持續暴露在寒氣之下，體力減少','凍傷','持続的な冷気によりHPが減少する。','동상','지속적으로 냉기에 노출되어 체력이 감소합니다.');
